import night from "@/illustrations/generated/night.json";
import { LayeredVector } from "./LayeredVector";

// The night-shift plant for the homepage problem section, generated by
// `npm run build:illustrations` (illustrations/model/night.ts). Its animated layer (the sensor,
// the data line, the fault glows and the gateway's signal) follows the `.night-scene` styles.
export function NightVector({ label, className }: { label: string; className?: string }) {
  return <LayeredVector scene={night} label={label} className={className} />;
}
